/* BattleQuiz - Science & Space.
 * Each entry carries both languages; `c` is the index of the correct option
 * in BOTH arrays, and `d` is the difficulty level 1-8.
 */
window.BANK = window.BANK || [];
window.BANK.push(
  { id:"sci001", t:"science", d:1, c:0, en:{q:"What do we call water when it freezes?",a:["Ice","Steam","Sand","Smoke"]}, tr:{q:"Su donunca ona ne denir?",a:["Buz","Buhar","Kum","Duman"]}, ex:{en:"Cooling below 0°C slows water molecules until they lock into a solid pattern.",tr:"Su 0°C altına inince moleküller yavaşlar ve katı bir düzende kilitlenir."} },
  { id:"sci002", t:"science", d:1, c:0, en:{q:"What colour is the sky on a clear day?",a:["Blue","Green","Red","Brown"]}, tr:{q:"Açık bir günde gökyüzü ne renktir?",a:["Mavi","Yeşil","Kırmızı","Kahverengi"]}, ex:{en:"Air scatters blue light from sunlight more than other colours, so the sky looks blue.",tr:"Hava, güneş ışığındaki mavi rengi diğer renklerden daha çok saçtığı için gökyüzü mavi görünür."} },
  { id:"sci003", t:"science", d:1, c:0, en:{q:"Which part of the body do we hear sounds with?",a:["Ears","Eyes","Nose","Feet"]}, tr:{q:"Sesleri hangi organımızla duyarız?",a:["Kulak","Göz","Burun","Ayak"]}, ex:{en:"Sound waves make the eardrum vibrate, and nerves turn that vibration into what we hear.",tr:"Ses dalgaları kulak zarını titreştirir, sinirler de bu titreşimi duyduğumuz sese çevirir."} },
  { id:"sci004", t:"science", d:1, c:0, en:{q:"What is the big bright round thing we see in the sky at night?",a:["The Moon","The Sun","A cloud","A rainbow"]}, tr:{q:"Gece gökyüzünde gördüğümüz büyük parlak yuvarlak nedir?",a:["Ay","Güneş","Bulut","Gökkuşağı"]}, ex:{en:"The Moon has no light of its own; it just reflects sunlight back to us at night.",tr:"Ay'ın kendi ışığı yoktur; geceleri sadece güneş ışığını bize yansıtır."} },
  { id:"sci005", t:"science", d:1, c:0, en:{q:"A magnet will stick to which of these?",a:["An iron nail","A wooden spoon","A glass cup","A plastic straw"]}, tr:{q:"Bir mıknatıs bunlardan hangisine yapışır?",a:["Demir çivi","Tahta kaşık","Cam bardak","Plastik pipet"]}, ex:{en:"Magnets attract iron, steel and nickel, but not other metals like plastic or aluminium.",tr:"Mıknatıslar demir, çelik ve nikeli çeker; plastik veya alüminyum gibi diğer maddeleri çekmez."} },
  { id:"sci006", t:"science", d:1, c:0, en:{q:"When you stand in bright sunshine, what forms on the ground?",a:["A shadow","A rainbow","A cloud","A star"]}, tr:{q:"Parlak güneş ışığında dururken yerde ne oluşur?",a:["Gölge","Gökkuşağı","Bulut","Yıldız"]}, ex:{en:"A shadow forms where your body blocks light from reaching the ground behind you.",tr:"Gölge, vücudun ışığın arkandaki zemine ulaşmasını engellediği yerde oluşur."} },
  { id:"sci007", t:"science", d:1, c:0, en:{q:"Which of these floats on water?",a:["A plastic ball","A metal key","A stone","A coin"]}, tr:{q:"Bunlardan hangisi suyun üstünde yüzer?",a:["Plastik top","Metal anahtar","Taş","Madenî para"]}, ex:{en:"Objects less dense than water, like a light plastic ball, float instead of sinking.",tr:"Sudan daha az yoğun olan cisimler, hafif bir plastik top gibi, batmak yerine yüzer."} },
  { id:"sci008", t:"science", d:1, c:0, en:{q:"What happens to sugar when you stir it into a glass of water?",a:["It dissolves and disappears","It floats on the top","It turns into a stone","It turns into ice"]}, tr:{q:"Bir bardak suya şeker atıp karıştırınca ne olur?",a:["Suda çözünüp kaybolur","Suyun üstünde yüzer","Taşa dönüşür","Buza dönüşür"]}, ex:{en:"Dissolving breaks the sugar into pieces so tiny you can no longer see them in the water.",tr:"Erime, şekeri suda artık göremeyeceğin kadar küçük parçalara ayırır."} },
  { id:"sci009", t:"science", d:1, c:0, en:{q:"What do we put inside a TV remote control to make it work?",a:["A battery","Water","Sand","Sugar"]}, tr:{q:"Televizyon kumandasının çalışması için içine ne takılır?",a:["Pil","Su","Kum","Şeker"]}, ex:{en:"A battery stores chemical energy and turns it into electricity when the remote needs it.",tr:"Pil kimyasal enerji depolar ve kumanda ihtiyaç duyduğunda bunu elektriğe çevirir."} },
  { id:"sci010", t:"science", d:1, c:0, en:{q:"What do we take into our body when we breathe in?",a:["Air","Water","Sand","Milk"]}, tr:{q:"Nefes alırken içimize çektiğimiz şey nedir?",a:["Hava","Su","Kum","Süt"]}, ex:{en:"Air contains oxygen, the gas your body needs to release energy from food.",tr:"Hava, vücudunun yiyeceklerden enerji açığa çıkarmak için ihtiyaç duyduğu oksijeni içerir."} },
  { id:"sci011", t:"science", d:1, c:0, en:{q:"A caterpillar grows up to become what?",a:["A butterfly","A fish","A bird","A frog"]}, tr:{q:"Bir tırtıl büyüyünce ne olur?",a:["Kelebek","Balık","Kuş","Kurbağa"]}, ex:{en:"Inside a chrysalis, the caterpillar's body is completely rebuilt into a butterfly.",tr:"Koza içinde tırtılın vücudu tamamen yeniden yapılanarak kelebeğe dönüşür."} },
  { id:"sci012", t:"science", d:1, c:0, en:{q:"What do we use our teeth for?",a:["Chewing food","Seeing in the dark","Smelling flowers","Holding a pencil"]}, tr:{q:"Dişlerimizi ne için kullanırız?",a:["Yiyecek çiğnemek","Karanlıkta görmek","Çiçek koklamak","Kalem tutmak"]}, ex:{en:"Teeth cut and grind food into small pieces so it is easier to swallow and digest.",tr:"Dişler yiyeceği küçük parçalara ayırır, böylece yutmak ve sindirmek kolaylaşır."} },
  { id:"sci013", t:"science", d:1, c:0, en:{q:"What are most windows made of?",a:["Glass","Bread","Wool","Paper"]}, tr:{q:"Pencereler çoğunlukla neyden yapılır?",a:["Cam","Ekmek","Yün","Kâğıt"]}, ex:{en:"Glass is used for windows because it is hard, smooth and lets light pass straight through.",tr:"Cam pencerelerde kullanılır çünkü serttir, düzgündür ve ışığın doğrudan geçmesine izin verir."} },
  { id:"sci014", t:"science", d:1, k:"tf", v:false, en:{q:"The Earth has two moons."}, tr:{q:"Dünya'nın iki ayı vardır."}, ex:{en:"Earth has exactly one natural moon, simply called the Moon.",tr:"Dünya'nın tam olarak bir doğal uydusu vardır, adı Ay'dır."} },
  { id:"sci015", t:"science", d:1, k:"tf", v:true, en:{q:"We use our tongue to taste food."}, tr:{q:"Yiyeceklerin tadını dilimizle alırız."}, ex:{en:"Taste buds on the tongue sense flavours like sweet, salty, sour and bitter.",tr:"Dildeki tat tomurcukları tatlı, tuzlu, ekşi ve acı gibi tatları algılar."} },
  { id:"sci016", t:"science", d:1, k:"tf", v:true, en:{q:"Plants need water to grow."}, tr:{q:"Bitkilerin büyümek için suya ihtiyacı vardır."}, ex:{en:"Plants use water, along with light and air, to make their own food inside their leaves.",tr:"Bitkiler, ışık ve havayla birlikte suyu kullanarak yapraklarında kendi besinlerini üretir."} },
  { id:"sci017", t:"science", d:1, k:"tf", v:false, en:{q:"A metal spoon left in hot soup stays cold."}, tr:{q:"Sıcak çorbanın içinde bırakılan metal kaşık soğuk kalır."}, ex:{en:"Metal conducts heat well, so a spoon left in hot soup quickly warms up itself.",tr:"Metal ısıyı iyi ilettiği için sıcak çorbada bırakılan kaşık hızla ısınır."} },
  { id:"sci018", t:"science", d:1, k:"tf", v:true, en:{q:"Our heart beats inside our chest."}, tr:{q:"Kalbimiz göğsümüzün içinde atar."}, ex:{en:"The heart sits inside the chest, protected by the ribcage, and pumps blood all day.",tr:"Kalp göğüs kafesi tarafından korunan göğüs boşluğunda bulunur ve gün boyu kan pompalar."} },
  { id:"sci019", t:"science", d:1, k:"tf", v:false, en:{q:"Birds have teeth in their beaks for chewing food."}, tr:{q:"Kuşların yiyecek çiğnemek için gagalarında dişleri vardır."}, ex:{en:"Birds have no teeth; they swallow food whole or peck it into pieces with their beak.",tr:"Kuşların dişi yoktur; yiyeceği ya bütün yutar ya da gagasıyla parçalara ayırır."} },
  { id:"sci020", t:"science", d:2, c:0, en:{q:"Which of these is a liquid?",a:["Water","Stone","Wood","Iron"]}, tr:{q:"Bunlardan hangisi sıvıdır?",a:["Su","Taş","Tahta","Demir"]}, ex:{en:"A liquid, unlike a solid, flows and takes the shape of whatever container holds it.",tr:"Sıvı, katıdan farklı olarak akar ve içine konduğu kabın şeklini alır."} },
  { id:"sci021", t:"science", d:2, c:0, en:{q:"What do plants need from the Sun in order to grow?",a:["Light","Sound","Wind","Snow"]}, tr:{q:"Bitkiler büyümek için Güneş'ten neye ihtiyaç duyar?",a:["Işık","Ses","Rüzgâr","Kar"]}, ex:{en:"Plants use light energy from the Sun to turn water and air into food, a process called photosynthesis.",tr:"Bitkiler, suyu ve havayı besine çevirmek için Güneş'ten gelen ışık enerjisini kullanır; buna fotosentez denir."} },
  { id:"sci022", t:"science", d:2, c:0, en:{q:"Which star is closest to the Earth?",a:["The Sun","Polaris","Sirius","Vega"]}, tr:{q:"Dünya'ya en yakın yıldız hangisidir?",a:["Güneş","Kutup Yıldızı","Sirius","Vega"]}, ex:{en:"The Sun is the star nearest to Earth, about 150 million kilometres away.",tr:"Güneş, Dünya'ya yaklaşık 150 milyon kilometre uzaklıktaki en yakın yıldızdır."} },
  { id:"sci023", t:"science", d:2, c:0, en:{q:"How many planets are there in our Solar System?",a:["Eight","Six","Ten","Twelve"]}, tr:{q:"Güneş Sistemi'nde kaç gezegen vardır?",a:["Sekiz","Altı","On","On iki"]}, ex:{en:"There are eight planets since Pluto was reclassified as a dwarf planet in 2006.",tr:"Plüton 2006'da cüce gezegen sayıldığından beri Güneş Sistemi'nde sekiz gezegen vardır."} },
  { id:"sci024", t:"science", d:2, c:0, en:{q:"Which object travels around the Earth?",a:["The Moon","The Sun","Mars","Venus"]}, tr:{q:"Dünya'nın etrafında hangi gök cismi döner?",a:["Ay","Güneş","Mars","Venüs"]}, ex:{en:"The Moon is held by Earth's gravity and circles it about once every month.",tr:"Ay, Dünya'nın çekim gücüyle tutulur ve yaklaşık her ayda bir kez etrafında döner."} },
  { id:"sci025", t:"science", d:2, c:0, en:{q:"Which gas in the air does our body need to stay alive?",a:["Oxygen","Nitrogen","Helium","Carbon dioxide"]}, tr:{q:"Vücudumuz yaşamak için havadaki hangi gaza ihtiyaç duyar?",a:["Oksijen","Azot","Helyum","Karbondioksit"]}, ex:{en:"Our cells use oxygen from the air to release the energy stored in food.",tr:"Hücrelerimiz, yiyeceklerde depolanan enerjiyi açığa çıkarmak için havadaki oksijeni kullanır."} },
  { id:"sci026", t:"science", d:2, c:0, en:{q:"What must an object do in order to make a sound?",a:["Vibrate","Get colder","Change colour","Get heavier"]}, tr:{q:"Bir cismin ses çıkarması için ne yapması gerekir?",a:["Titremesi","Soğuması","Renk değiştirmesi","Ağırlaşması"]}, ex:{en:"Sound is made of vibrations travelling through the air, so a still object makes no sound.",tr:"Ses, havada yayılan titreşimlerden oluşur; bu yüzden hareketsiz bir cisim ses çıkarmaz."} },
  { id:"sci027", t:"science", d:2, c:0, en:{q:"Which instrument do scientists use to look at very tiny things?",a:["A microscope","A telescope","A thermometer","A compass"]}, tr:{q:"Bilim insanları çok küçük şeyleri incelemek için hangi aleti kullanır?",a:["Mikroskop","Teleskop","Termometre","Pusula"]}, ex:{en:"A microscope uses lenses to bend light and make tiny objects look much bigger.",tr:"Mikroskop, ışığı kırarak küçük cisimleri çok daha büyük gösteren mercekler kullanır."} },
  { id:"sci028", t:"science", d:2, c:0, en:{q:"Which organ does your food reach after you swallow it?",a:["The stomach","The lungs","The heart","The brain"]}, tr:{q:"Yuttuğun yemek hangi organa ulaşır?",a:["Mide","Akciğerler","Kalp","Beyin"]}, ex:{en:"After you swallow, food travels down a tube called the oesophagus into the stomach.",tr:"Yutulan yiyecek, yemek borusu adı verilen bir kanaldan geçerek mideye ulaşır."} },
  { id:"sci029", t:"science", d:2, c:0, en:{q:"What do we call all the bones of the body together?",a:["The skeleton","A muscle","The skin","The blood"]}, tr:{q:"Vücuttaki bütün kemiklerin oluşturduğu yapıya ne denir?",a:["İskelet","Kas","Deri","Kan"]}, ex:{en:"The skeleton is all the bones together; it holds the body up and protects organs inside.",tr:"İskelet, tüm kemiklerin bir arada oluşturduğu yapıdır; vücudu ayakta tutar ve iç organları korur."} },
  { id:"sci030", t:"science", d:2, c:0, en:{q:"Which part of a plant takes in water from the soil?",a:["The roots","The flowers","The leaves","The fruit"]}, tr:{q:"Bitkinin hangi kısmı topraktan su alır?",a:["Kökler","Çiçekler","Yapraklar","Meyveler"]}, ex:{en:"Roots grow down into the soil and soak up water like a sponge.",tr:"Kökler toprağa doğru uzanır ve süngerin suyu emmesi gibi suyu emer."} },
  { id:"sci031", t:"science", d:2, c:0, en:{q:"What do we call the energy that flows through wires to light a lamp?",a:["Electricity","Sound","Wind","Water"]}, tr:{q:"Bir lambayı yakmak için tellerden akan enerjiye ne denir?",a:["Elektrik","Ses","Rüzgâr","Su"]}, ex:{en:"Electricity is the flow of tiny charged particles through a wire, powering the lamp.",tr:"Elektrik, tellerin içinde akan küçük yüklü parçacıkların hareketidir ve lambayı çalıştırır."} },
  { id:"sci032", t:"science", d:2, k:"tf", v:false, en:{q:"The Moon makes its own light, just like the Sun."}, tr:{q:"Ay, tıpkı Güneş gibi kendi ışığını üretir."}, ex:{en:"The Moon has no light of its own; what we see is sunlight bouncing off its surface.",tr:"Ay'ın kendi ışığı yoktur; gördüğümüz şey Güneş ışığının yüzeyinden yansımasıdır."} },
  { id:"sci033", t:"science", d:2, k:"tf", v:false, en:{q:"Human blood is blue while it is inside the body."}, tr:{q:"İnsan kanı vücudun içindeyken mavi renktedir."}, ex:{en:"Blood is always red, whether bright with oxygen or darker without it; it never turns blue.",tr:"Kan her zaman kırmızıdır, oksijenliyken açık, oksijensizken koyu kırmızıdır; asla maviye dönüşmez."} },
  { id:"sci034", t:"science", d:2, k:"tf", v:true, en:{q:"Water freezes and turns into ice at 0 degrees Celsius."}, tr:{q:"Su, 0 santigrat derecede donarak buza dönüşür."}, ex:{en:"0 degrees Celsius is exactly the temperature at which water freezes and ice melts.",tr:"0 santigrat derece, suyun donduğu ve buzun eridiği tam sıcaklıktır."} },
  { id:"sci035", t:"science", d:2, k:"tf", v:true, en:{q:"Isaac Newton is the scientist famous for his work on gravity."}, tr:{q:"Isaac Newton, yer çekimi üzerine yaptığı çalışmalarla ünlü bir bilim insanıdır."}, ex:{en:"Newton described gravity, the force that pulls objects like an apple, or a planet, towards each other.",tr:"Newton, elmayı ya da bir gezegeni birbirine çeken kuvvet olan yer çekimini tanımladı."} },
  { id:"sci036", t:"science", d:2, k:"tf", v:true, en:{q:"A metal spoon left in hot soup heats up faster than a wooden one."}, tr:{q:"Sıcak çorbanın içinde bırakılan metal kaşık, tahta kaşıktan daha çabuk ısınır."}, ex:{en:"Metal conducts heat far better than wood, so it warms up much faster in something hot.",tr:"Metal, ısıyı tahtadan çok daha iyi ilettiği için sıcak bir ortamda çok daha hızlı ısınır."} },
  { id:"sci037", t:"science", d:2, k:"tf", v:false, en:{q:"Fish breathe underwater using their lungs."}, tr:{q:"Balıklar su altında akciğerleriyle nefes alır."}, ex:{en:"Fish breathe with gills, which pull dissolved oxygen straight out of the water.",tr:"Balıklar solungaçlarıyla nefes alır; solungaçlar suda erimiş oksijeni doğrudan çeker."} },
  { id:"sci038", t:"science", d:3, c:0, en:{q:"What is the chemical formula for water?",a:["H₂O","CO₂","O₂","NaCl"]}, tr:{q:"Suyun kimyasal formülü nedir?",a:["H₂O","CO₂","O₂","NaCl"]}, ex:{en:"Each water molecule is two hydrogen atoms bonded to one oxygen atom, giving H₂O.",tr:"Her su molekülü iki hidrojen atomunun bir oksijen atomuna bağlanmasından oluşur, yani H₂O."} },
  { id:"sci039", t:"science", d:3, c:0, en:{q:"Which planet is known as the Red Planet?",a:["Mars","Venus","Mercury","Jupiter"]}, tr:{q:"Hangi gezegen Kızıl Gezegen olarak bilinir?",a:["Mars","Venüs","Merkür","Jüpiter"]}, ex:{en:"Mars looks red because its surface is covered in iron oxide, the same rust you see on old metal.",tr:"Mars kırmızı görünür çünkü yüzeyi, eski metallerde gördüğün pas gibi demir oksitle kaplıdır."} },
  { id:"sci040", t:"science", d:3, c:0, en:{q:"At what temperature does water boil at sea level?",a:["100 °C","50 °C","120 °C","90 °C"]}, tr:{q:"Deniz seviyesinde su kaç derecede kaynar?",a:["100 °C","50 °C","120 °C","90 °C"]}, ex:{en:"At sea level, air pressure lets water boil at exactly 100°C; less pressure lowers that point.",tr:"Deniz seviyesindeki hava basıncı, suyun tam olarak 100°C'de kaynamasını sağlar; basınç düşerse bu sıcaklık da düşer."} },
  { id:"sci041", t:"science", d:3, c:0, en:{q:"What is the everyday name for the chemical sodium chloride?",a:["Salt","Sugar","Sand","Chalk"]}, tr:{q:"Sodyum klorür bileşiğinin günlük hayattaki adı nedir?",a:["Tuz","Şeker","Kum","Tebeşir"]}, ex:{en:"Table salt is the chemical sodium chloride, one sodium atom bonded to one chlorine atom.",tr:"Sofra tuzu, bir sodyum atomunun bir klor atomuna bağlanmasıyla oluşan sodyum klorür bileşiğidir."} },
  { id:"sci042", t:"science", d:3, c:0, en:{q:"What is it called when a liquid turns into a gas?",a:["Evaporation","Condensation","Melting","Freezing"]}, tr:{q:"Bir sıvının gaz hâline geçmesine ne ad verilir?",a:["Buharlaşma","Yoğuşma","Erime","Donma"]}, ex:{en:"Evaporation happens when a liquid's surface turns to gas, even below its boiling point.",tr:"Buharlaşma, bir sıvının yüzeyinin kaynama noktasının altında bile gaza dönüşmesidir."} },
  { id:"sci043", t:"science", d:3, c:0, en:{q:"Which of these metals is attracted to a magnet?",a:["Iron","Gold","Copper","Aluminium"]}, tr:{q:"Bu metallerden hangisi mıknatıs tarafından çekilir?",a:["Demir","Altın","Bakır","Alüminyum"]}, ex:{en:"Iron, along with nickel and cobalt, is one of the few metals a magnet pulls strongly.",tr:"Demir, nikel ve kobaltla birlikte bir mıknatısın güçlü şekilde çektiği az sayıdaki metalden biridir."} },
  { id:"sci044", t:"science", d:3, c:0, en:{q:"Which is the largest organ of the human body?",a:["The skin","The liver","The brain","The heart"]}, tr:{q:"İnsan vücudundaki en büyük organ hangisidir?",a:["Deri","Karaciğer","Beyin","Kalp"]}, ex:{en:"The skin covers the entire body, making it the largest organ by surface area and weight.",tr:"Deri tüm vücudu kapladığı için yüzey alanı ve ağırlık bakımından en büyük organdır."} },
  { id:"sci045", t:"science", d:3, c:0, en:{q:"What do we call an idea a scientist tests with an experiment?",a:["A hypothesis","A conclusion","A measurement","An observation"]}, tr:{q:"Bilim insanının deneyle sınadığı fikre ne ad verilir?",a:["Hipotez","Sonuç","Ölçüm","Gözlem"]}, ex:{en:"A hypothesis is an educated guess that an experiment is designed to test.",tr:"Hipotez, bir deneyle sınanmak üzere ortaya konan mantıklı bir tahmindir."} },
  { id:"sci046", t:"science", d:3, c:0, en:{q:"What are the tiny building blocks that all matter is made of called?",a:["Atoms","Cells","Fossils","Magnets"]}, tr:{q:"Tüm maddeleri oluşturan çok küçük yapı taşlarına ne ad verilir?",a:["Atomlar","Hücreler","Fosiller","Mıknatıslar"]}, ex:{en:"Atoms are the smallest particles that keep the properties of an element; everything is built from them.",tr:"Atomlar, bir elementin özelliklerini taşıyan en küçük parçacıklardır; her şey atomlardan oluşur."} },
  { id:"sci047", t:"science", d:3, c:0, en:{q:"Which instrument is used to look at things too small to see?",a:["A microscope","A telescope","A barometer","A compass"]}, tr:{q:"Gözle görülemeyecek kadar küçük şeyleri incelemek için hangi alet kullanılır?",a:["Mikroskop","Teleskop","Barometre","Pusula"]}, ex:{en:"A microscope's lenses bend light to magnify things far too small to see with the eye alone.",tr:"Mikroskobun mercekleri, çıplak gözle görülemeyecek kadar küçük şeyleri büyütmek için ışığı kırar."} },
  { id:"sci048", t:"science", d:3, c:0, en:{q:"Which of these materials conducts electricity well?",a:["Copper","Plastic","Rubber","Glass"]}, tr:{q:"Bu maddelerden hangisi elektriği iyi iletir?",a:["Bakır","Plastik","Lastik","Cam"]}, ex:{en:"Copper's electrons move freely, letting electric current pass through it easily, which is why it is used in wires.",tr:"Bakırın elektronları serbestçe hareket eder, bu yüzden elektrik akımı kolayca geçer ve tellerde kullanılır."} },
  { id:"sci049", t:"science", d:3, k:"tf", v:true, en:{q:"Sound travels faster through water than through air."}, tr:{q:"Ses suda havadakinden daha hızlı yayılır."}, ex:{en:"Sound moves faster through water because its molecules are packed closer together than in air.",tr:"Sesin sudaki hızı daha fazladır çünkü su moleküllerinin arası havadakinden daha sıkışıktır."} },
  { id:"sci050", t:"science", d:3, k:"tf", v:false, en:{q:"The bubbles in fizzy drinks are made of oxygen gas."}, tr:{q:"Gazlı içeceklerdeki baloncuklar oksijen gazından oluşur."}, ex:{en:"Fizzy drink bubbles are carbon dioxide gas, dissolved in the liquid under pressure until the bottle opens.",tr:"Gazlı içeceklerdeki baloncuklar, şişe açılana kadar sıvıda basınç altında çözünmüş karbondioksit gazıdır."} },
  { id:"sci051", t:"science", d:3, k:"tf", v:true, en:{q:"Chlorophyll is the green substance in leaves that plants use to make their own food."}, tr:{q:"Klorofil, bitkilerin kendi besinini üretmesini sağlayan, yapraklardaki yeşil maddedir."}, ex:{en:"Chlorophyll absorbs sunlight and gives leaves the energy to make food, and their green colour.",tr:"Klorofil, güneş ışığını emerek yaprakların besin üretmesini sağlar ve onlara yeşil rengini verir."} },
  { id:"sci052", t:"science", d:3, k:"tf", v:true, en:{q:"We see lightning before we hear thunder because light travels faster than sound."}, tr:{q:"Şimşeği gök gürültüsünden önce görürüz, çünkü ışık sesten daha hızlı yayılır."}, ex:{en:"Light travels about a million times faster than sound, so the flash always arrives first.",tr:"Işık sesten yaklaşık bir milyon kat daha hızlı gittiği için şimşek her zaman önce ulaşır."} },
  { id:"sci053", t:"science", d:3, k:"tf", v:false, en:{q:"Veins are the blood vessels that carry blood away from the heart to the rest of the body."}, tr:{q:"Kanı kalpten vücudun geri kalan bölümlerine taşıyan damarlara toplardamar denir."}, ex:{en:"Arteries carry blood away from the heart; veins are the ones that carry it back.",tr:"Kanı kalpten uzağa taşıyan atardamarlardır; toplardamarlar ise kanı geri taşır."} },
  { id:"sci054", t:"science", d:3, k:"tf", v:false, en:{q:"Marie Curie, the scientist known for her work on radioactivity, was born in France."}, tr:{q:"Radyoaktivite üzerine çalışmalarıyla tanınan bilim insanı Marie Curie Fransa'da doğmuştur."}, ex:{en:"Marie Curie was born in Warsaw, Poland, and later moved to France to study and work.",tr:"Marie Curie, Polonya'nın Varşova kentinde doğdu ve sonradan çalışmak için Fransa'ya taşındı."} },
  { id:"sci055", t:"science", d:4, c:0, en:{q:"Which gas do plants take in during photosynthesis?",a:["Carbon dioxide","Oxygen","Nitrogen","Hydrogen"]}, tr:{q:"Bitkiler fotosentez sırasında hangi gazı alır?",a:["Karbondioksit","Oksijen","Azot","Hidrojen"]}, ex:{en:"Plants pull carbon dioxide from the air and use it, with light and water, to build their own food.",tr:"Bitkiler havadan karbondioksit çeker ve bunu ışık ile suyla birlikte kendi besinini üretmek için kullanır."} },
  { id:"sci056", t:"science", d:4, c:0, en:{q:"Which force pulls objects towards the Earth?",a:["Gravity","Friction","Magnetism","Pressure"]}, tr:{q:"Cisimleri Dünya'ya doğru çeken kuvvet hangisidir?",a:["Yer çekimi","Sürtünme","Manyetizma","Basınç"]}, ex:{en:"Gravity is the pulling force between any two masses; Earth's mass is huge, so its pull is strong.",tr:"Yer çekimi, herhangi iki kütle arasındaki çekim kuvvetidir; Dünya'nın kütlesi çok büyük olduğu için çekimi güçlüdür."} },
  { id:"sci057", t:"science", d:4, c:0, en:{q:"Which part of the blood carries oxygen around the body?",a:["Red blood cells","White blood cells","Platelets","Plasma"]}, tr:{q:"Kanın hangi bölümü vücutta oksijen taşır?",a:["Alyuvarlar","Akyuvarlar","Trombositler","Plazma"]}, ex:{en:"Red blood cells carry a protein called haemoglobin that grabs oxygen and releases it around the body.",tr:"Alyuvarlar, oksijeni tutup vücuda taşıyan hemoglobin adlı bir proteini içerir."} },
  { id:"sci058", t:"science", d:4, c:0, en:{q:"Roughly how long does sunlight take to reach the Earth?",a:["About 8 minutes","About 8 seconds","About 8 hours","About 8 days"]}, tr:{q:"Güneş ışığının Dünya'ya ulaşması yaklaşık ne kadar sürer?",a:["Yaklaşık 8 dakika","Yaklaşık 8 saniye","Yaklaşık 8 saat","Yaklaşık 8 gün"]}, ex:{en:"Light travels about 150 million kilometres from the Sun at 300,000 km per second, taking roughly 8 minutes.",tr:"Işık, Güneş'ten saniyede 300.000 km hızla yaklaşık 150 milyon kilometre yol alır, bu da yaklaşık 8 dakika sürer."} },
  { id:"sci059", t:"science", d:4, c:0, en:{q:"Our Solar System is part of which galaxy?",a:["The Milky Way","Andromeda","The Whirlpool Galaxy","The Sombrero Galaxy"]}, tr:{q:"Güneş Sistemimiz hangi galaksinin içinde yer alır?",a:["Samanyolu","Andromeda","Girdap Galaksisi","Sombrero Galaksisi"]}, ex:{en:"The Milky Way is the galaxy of hundreds of billions of stars that contains our Sun and planets.",tr:"Samanyolu, Güneşimizi ve gezegenlerimizi içeren, yüz milyarlarca yıldızdan oluşan galaksidir."} },
  { id:"sci060", t:"science", d:4, c:0, en:{q:"What causes day and night on Earth?",a:["Earth spinning on its axis","Earth orbiting the Sun","The Moon blocking the Sun","Clouds covering the sky"]}, tr:{q:"Dünya'da gece ve gündüzün oluşmasının sebebi nedir?",a:["Dünya'nın kendi ekseni etrafında dönmesi","Dünya'nın Güneş etrafında dolanması","Ay'ın Güneş'i engellemesi","Bulutların gökyüzünü kaplaması"]}, ex:{en:"Earth spins on its axis once roughly every 24 hours, turning each side towards and away from the Sun.",tr:"Dünya, ekseni etrafında yaklaşık her 24 saatte bir tam tur atar ve her yüzü sırayla Güneş'e döner."} },
  { id:"sci061", t:"science", d:4, c:0, en:{q:"Which is the longest bone in the human body?",a:["The thigh bone (femur)","The upper arm bone","The shin bone","The collarbone"]}, tr:{q:"İnsan vücudundaki en uzun kemik hangisidir?",a:["Uyluk kemiği (femur)","Pazı kemiği","Kaval kemiği","Köprücük kemiği"]}, ex:{en:"The femur, running from hip to knee, is both the longest and the strongest bone in the body.",tr:"Uyluk kemiği (femur), kalçadan dize kadar uzanır ve vücudun hem en uzun hem de en güçlü kemiğidir."} },
  { id:"sci062", t:"science", d:4, c:0, en:{q:"Which organ absorbs most of the nutrients from our food?",a:["The small intestine","The stomach","The liver","The large intestine"]}, tr:{q:"Besinlerdeki besleyici maddelerin çoğu hangi organda emilir?",a:["İnce bağırsak","Mide","Karaciğer","Kalın bağırsak"]}, ex:{en:"The small intestine's walls are lined with tiny finger-like villi that soak nutrients into the blood.",tr:"İnce bağırsağın duvarları, besinleri kana emen küçük parmak şeklindeki villuslarla kaplıdır."} },
  { id:"sci063", t:"science", d:4, c:0, en:{q:"Which part of a cell holds the DNA and controls its activities?",a:["The nucleus","The ribosome","The cell membrane","The vacuole"]}, tr:{q:"Hücrenin DNA'yı barındıran ve faaliyetlerini yöneten kısmı hangisidir?",a:["Çekirdek","Ribozom","Hücre zarı","Koful"]}, ex:{en:"The nucleus stores a cell's DNA, the instructions that direct everything the cell does.",tr:"Çekirdek, hücrenin yaptığı her şeyi yönlendiren talimatları taşıyan DNA'yı saklar."} },
  { id:"sci064", t:"science", d:4, c:0, en:{q:"What is the chemical name for ordinary table salt?",a:["Sodium chloride","Calcium carbonate","Potassium nitrate","Sodium hydroxide"]}, tr:{q:"Sofra tuzunun kimyasal adı nedir?",a:["Sodyum klorür","Kalsiyum karbonat","Potasyum nitrat","Sodyum hidroksit"]}, ex:{en:"Table salt's chemical name, sodium chloride, describes the two elements it is made from.",tr:"Sofra tuzunun kimyasal adı olan sodyum klorür, tuzu oluşturan iki elementi anlatır."} },
  { id:"sci065", t:"science", d:4, c:0, en:{q:"What do we call a material that lets electricity pass through easily?",a:["A conductor","An insulator","A magnet","An alloy"]}, tr:{q:"Elektriği kolayca ileten maddelere ne ad verilir?",a:["İletken","Yalıtkan","Mıknatıs","Alaşım"]}, ex:{en:"A conductor lets electric charge move through it easily; most metals conduct electricity well.",tr:"İletken, elektrik yükünün kolayca içinden geçmesine izin veren maddedir; çoğu metal iyi iletkendir."} },
  { id:"sci066", t:"science", d:4, c:0, en:{q:"What happens when the north poles of two magnets are brought together?",a:["They push each other away","They pull each other together","Nothing happens at all","They lose their magnetism"]}, tr:{q:"İki mıknatısın kuzey kutupları birbirine yaklaştırılınca ne olur?",a:["Birbirlerini iterler","Birbirlerini çekerler","Hiçbir şey olmaz","Manyetikliklerini kaybederler"]}, ex:{en:"Like magnetic poles push each other away; only opposite poles, north and south, pull together.",tr:"Aynı kutuplar birbirini iter; sadece zıt kutuplar, yani kuzey ve güney, birbirini çeker."} },
  { id:"sci067", t:"science", d:4, c:0, en:{q:"In an experiment, what do we call the factor the scientist changes on purpose?",a:["The independent variable","The dependent variable","The control variable","The hypothesis"]}, tr:{q:"Bir deneyde bilim insanının bilerek değiştirdiği etkene ne ad verilir?",a:["Bağımsız değişken","Bağımlı değişken","Kontrol değişkeni","Hipotez"]}, ex:{en:"The independent variable is the one thing the scientist deliberately changes to see its effect.",tr:"Bağımsız değişken, bilim insanının etkisini görmek için kasıtlı olarak değiştirdiği tek şeydir."} },
  { id:"sci068", t:"science", d:4, c:0, en:{q:"Which scientist won Nobel Prizes in two different sciences?",a:["Marie Curie","Albert Einstein","Charles Darwin","Galileo Galilei"]}, tr:{q:"Hangi bilim insanı iki farklı bilim dalında Nobel Ödülü kazandı?",a:["Marie Curie","Albert Einstein","Charles Darwin","Galileo Galilei"]}, ex:{en:"Marie Curie won the Nobel Prize in Physics in 1903 and the Nobel Prize in Chemistry in 1911.",tr:"Marie Curie, 1903'te Fizik ve 1911'de Kimya dallarında Nobel Ödülü kazandı."} },
  { id:"sci069", t:"science", d:4, k:"tf", v:false, en:{q:"The Great Wall of China is visible to the naked eye from the Moon."}, tr:{q:"Çin Seddi, Ay'dan çıplak gözle görülebilir."}, ex:{en:"The Great Wall is long but very narrow, and no human-made object is actually visible from the Moon.",tr:"Çin Seddi uzun ama çok dardır; hiçbir insan yapımı yapı Ay'dan aslında görülemez."} },
  { id:"sci070", t:"science", d:4, k:"tf", v:true, en:{q:"The Moon always keeps the same side facing the Earth."}, tr:{q:"Ay, Dünya'ya her zaman aynı yüzünü gösterir."}, ex:{en:"The Moon rotates at the same rate it orbits Earth, so it is tidally locked and always shows one face.",tr:"Ay, Dünya çevresindeki dönüşüyle aynı hızda kendi ekseninde döner, bu yüzden bize hep aynı yüzünü gösterir."} },
  { id:"sci071", t:"science", d:4, k:"tf", v:false, en:{q:"Water shrinks and takes up less space when it freezes into ice."}, tr:{q:"Su donup buza dönüştüğünde büzüşür ve daha az yer kaplar."}, ex:{en:"Water is unusual: it expands as it freezes, so ice is less dense than liquid water and floats.",tr:"Su alışılmadıktır: donunca genişler, bu yüzden buz sıvı sudan daha az yoğundur ve yüzer."} },
  { id:"sci072", t:"science", d:4, k:"tf", v:false, en:{q:"Isaac Newton was the first scientist to propose that the Earth moves around the Sun."}, tr:{q:"Dünya'nın Güneş'in etrafında döndüğünü ilk öne süren bilim insanı Isaac Newton'dur."}, ex:{en:"Nicolaus Copernicus proposed Earth orbits the Sun; Newton later explained gravity, the force behind it.",tr:"Dünya'nın Güneş etrafında döndüğünü öne süren Kopernik'ti; Newton ise bunun arkasındaki yer çekimini açıkladı."} },
  { id:"sci073", t:"science", d:4, k:"tf", v:true, en:{q:"Diamond and graphite are both made of the same element, carbon."}, tr:{q:"Elmas da grafit de aynı elementten, yani karbondan oluşur."}, ex:{en:"Diamond and graphite are both pure carbon; their atoms are just arranged in different patterns.",tr:"Elmas ve grafit ikisi de saf karbondur; atomları yalnızca farklı düzenlerde dizilmiştir."} },
  { id:"sci074", t:"science", d:4, k:"tf", v:true, en:{q:"Bile is made by the liver and stored in the gall bladder."}, tr:{q:"Safra, karaciğerde üretilir ve safra kesesinde depolanır."}, ex:{en:"The liver produces bile, and the gall bladder stores it until it is needed to digest fat.",tr:"Karaciğer safra üretir, safra kesesi de yağların sindirilmesi için gerekene kadar bunu depolar."} },
  { id:"sci075", t:"science", d:4, k:"tf", v:false, en:{q:"In plant cells, the green pigment chlorophyll is found inside the mitochondria."}, tr:{q:"Bitki hücrelerinde yeşil renkli klorofil, mitokondrinin içinde bulunur."}, ex:{en:"Chlorophyll is held inside chloroplasts, not mitochondria, which instead release energy from food.",tr:"Klorofil mitokondride değil, kloroplastlarda bulunur; mitokondri ise besinden enerji açığa çıkarır."} },
  { id:"sci076", t:"science", d:5, c:0, en:{q:"What is the chemical symbol for gold?",a:["Au","Ag","Go","Gd"]}, tr:{q:"Altının kimyasal sembolü nedir?",a:["Au","Ag","Go","Gd"]}, ex:{en:"Gold's symbol Au comes from its Latin name, aurum.",tr:"Altının simgesi olan Au, Latince adı 'aurum'dan gelir."} },
  { id:"sci077", t:"science", d:5, c:0, en:{q:"Which gas makes up roughly 78% of Earth's atmosphere?",a:["Nitrogen","Oxygen","Carbon dioxide","Argon"]}, tr:{q:"Dünya atmosferinin yaklaşık %78'ini hangi gaz oluşturur?",a:["Azot","Oksijen","Karbondioksit","Argon"]}, ex:{en:"Nitrogen makes up about 78% of the air, with oxygen at around 21% and other gases the rest.",tr:"Havanın yaklaşık %78'i azottur, %21'i oksijendir, geri kalanı diğer gazlardır."} },
  { id:"sci078", t:"science", d:5, c:0, en:{q:"How many chambers does the human heart have?",a:["Four","Two","Three","Six"]}, tr:{q:"İnsan kalbinin kaç odacığı vardır?",a:["Dört","İki","Üç","Altı"]}, ex:{en:"The heart has two upper chambers (atria) and two lower chambers (ventricles), four in total.",tr:"Kalbin iki üst odacığı (kulakçık) ve iki alt odacığı (karıncık) vardır, toplam dört odacık."} },
  { id:"sci079", t:"science", d:5, c:0, en:{q:"Which part of a cell releases energy from glucose during aerobic respiration?",a:["Mitochondria","Ribosome","Nucleus","Cell membrane"]}, tr:{q:"Hücrenin hangi kısmı oksijenli solunumda glikozdan enerji açığa çıkarır?",a:["Mitokondri","Ribozom","Çekirdek","Hücre zarı"]}, ex:{en:"Mitochondria break down glucose using oxygen to release the energy a cell needs to work.",tr:"Mitokondri, hücrenin çalışması için gereken enerjiyi açığa çıkarmak üzere glikozu oksijenle parçalar."} },
  { id:"sci080", t:"science", d:5, c:0, en:{q:"How many chromosomes are there in a normal human body cell?",a:["46","23","48","92"]}, tr:{q:"Normal bir insan vücut hücresinde kaç kromozom bulunur?",a:["46","23","48","92"]}, ex:{en:"Human body cells normally hold 46 chromosomes, arranged as 23 matching pairs.",tr:"İnsan vücut hücrelerinde normalde 23 çift halinde dizilmiş 46 kromozom bulunur."} },
  { id:"sci081", t:"science", d:5, c:0, en:{q:"Which part of the brain mainly controls balance and coordination?",a:["Cerebellum","Cerebrum","Brain stem","Spinal cord"]}, tr:{q:"Beynin hangi bölümü esas olarak denge ve koordinasyonu kontrol eder?",a:["Beyincik","Büyük beyin","Beyin sapı","Omurilik"]}, ex:{en:"The cerebellum, at the back of the brain, fine-tunes movement and keeps the body balanced.",tr:"Beynin arkasında yer alan beyincik, hareketleri ince ayarlar ve vücudun dengesini sağlar."} },
  { id:"sci082", t:"science", d:5, c:0, en:{q:"Which gas is given off when an acid reacts with a metal such as zinc?",a:["Hydrogen","Oxygen","Carbon dioxide","Chlorine"]}, tr:{q:"Bir asit, çinko gibi bir metalle tepkimeye girdiğinde hangi gaz açığa çıkar?",a:["Hidrojen","Oksijen","Karbondioksit","Klor"]}, ex:{en:"When an acid reacts with a metal like zinc, it produces a salt and releases hydrogen gas.",tr:"Bir asit çinko gibi bir metalle tepkimeye girdiğinde, bir tuz oluşur ve hidrojen gazı açığa çıkar."} },
  { id:"sci083", t:"science", d:5, c:0, en:{q:"In the periodic table, what are the vertical columns of elements called?",a:["Groups","Periods","Shells","Series"]}, tr:{q:"Periyodik tabloda elementlerin dikey sütunlarına ne ad verilir?",a:["Gruplar","Periyotlar","Katmanlar","Seriler"]}, ex:{en:"Elements in the same vertical group share similar properties because they have the same outer electrons.",tr:"Aynı dikey grup içindeki elementler, dış elektron sayıları aynı olduğu için benzer özellikler gösterir."} },
  { id:"sci084", t:"science", d:5, c:0, en:{q:"What is it called when a solid turns straight into a gas without melting first?",a:["Sublimation","Condensation","Evaporation","Freezing"]}, tr:{q:"Bir katının önce erimeden doğrudan gaza dönüşmesine ne ad verilir?",a:["Süblimleşme","Yoğuşma","Buharlaşma","Donma"]}, ex:{en:"Sublimation skips the liquid stage entirely; solid carbon dioxide, dry ice, does this at room temperature.",tr:"Süblimleşme sıvı aşamasını tamamen atlar; katı karbondioksit, yani kuru buz, bunu oda sıcaklığında yapar."} },
  { id:"sci085", t:"science", d:5, c:0, en:{q:"Roughly how fast does light travel in a vacuum?",a:["About 300,000 km per second","About 300,000 km per hour","About 3,000 km per second","About 30 million km per second"]}, tr:{q:"Işık boşlukta yaklaşık hangi hızla yayılır?",a:["Saniyede yaklaşık 300.000 km","Saatte yaklaşık 300.000 km","Saniyede yaklaşık 3.000 km","Saniyede yaklaşık 30 milyon km"]}, ex:{en:"Light travels at almost exactly 300,000 kilometres every second in empty space.",tr:"Işık, boş uzayda saniyede neredeyse tam olarak 300.000 kilometre yol alır."} },
  { id:"sci086", t:"science", d:5, c:0, en:{q:"Sound waves cannot travel through which of these?",a:["A vacuum","Water","Steel","Air"]}, tr:{q:"Ses dalgaları bunlardan hangisinin içinden geçemez?",a:["Boşluk (vakum)","Su","Çelik","Hava"]}, ex:{en:"Sound needs particles to vibrate through, so it cannot travel across a vacuum, which has none.",tr:"Sesin yayılabilmesi için titreşecek parçacıklara ihtiyacı vardır, bu yüzden parçacığı olmayan boşlukta ilerleyemez."} },
  { id:"sci087", t:"science", d:5, c:0, en:{q:"What does a voltmeter measure in an electric circuit?",a:["Voltage","Current","Resistance","Power"]}, tr:{q:"Voltmetre bir elektrik devresinde neyi ölçer?",a:["Gerilim (voltaj)","Akım","Direnç","Güç"]}, ex:{en:"A voltmeter measures voltage, the electrical push that drives current around a circuit.",tr:"Voltmetre, bir devrede akımı iten elektriksel güç olan voltajı ölçer."} },
  { id:"sci088", t:"science", d:5, c:0, en:{q:"The Great Red Spot, a giant storm, is found on which planet?",a:["Jupiter","Saturn","Neptune","Venus"]}, tr:{q:"Dev bir fırtına olan Büyük Kırmızı Leke hangi gezegende bulunur?",a:["Jüpiter","Satürn","Neptün","Venüs"]}, ex:{en:"The Great Red Spot is a storm on Jupiter bigger than Earth that has raged for centuries.",tr:"Büyük Kırmızı Leke, Jüpiter'de Dünya'dan bile büyük olan ve yüzyıllardır süren bir fırtınadır."} },
  { id:"sci089", t:"science", d:5, c:0, en:{q:"In an experiment, what is the variable the scientist deliberately changes called?",a:["Independent variable","Dependent variable","Control variable","Control group"]}, tr:{q:"Bir deneyde bilim insanının bilerek değiştirdiği değişkene ne ad verilir?",a:["Bağımsız değişken","Bağımlı değişken","Kontrol değişkeni","Kontrol grubu"]}, ex:{en:"The independent variable is the single factor the scientist changes on purpose during the experiment.",tr:"Bağımsız değişken, deney sırasında bilim insanının kasıtlı olarak değiştirdiği tek etkendir."} },
  { id:"sci090", t:"science", d:5, c:0, en:{q:"Which scientist discovered penicillin in 1928?",a:["Alexander Fleming","Louis Pasteur","Edward Jenner","Marie Curie"]}, tr:{q:"1928'de penisilini hangi bilim insanı keşfetti?",a:["Alexander Fleming","Louis Pasteur","Edward Jenner","Marie Curie"]}, ex:{en:"Fleming noticed mould accidentally killing bacteria in a petri dish, leading him to penicillin.",tr:"Fleming, bir petri kabındaki küfün bakterileri kazara öldürdüğünü fark ederek penisiline ulaştı."} },
  { id:"sci091", t:"science", d:5, k:"tf", v:true, en:{q:"Helium was detected in the Sun before it was found on Earth."}, tr:{q:"Helyum, Dünya'da bulunmadan önce Güneş'te tespit edilmiştir."}, ex:{en:"Helium was first spotted in 1868 as an unknown line in sunlight, decades before it was found on Earth.",tr:"Helyum ilk kez 1868'de güneş ışığında bilinmeyen bir çizgi olarak fark edildi, Dünya'da bulunmasından onlarca yıl önce."} },
  { id:"sci092", t:"science", d:5, k:"tf", v:true, en:{q:"Venus takes longer to spin once on its axis than to complete one orbit of the Sun."}, tr:{q:"Venüs'ün kendi ekseni etrafında bir tam dönüşü, Güneş çevresindeki bir turundan daha uzun sürer."}, ex:{en:"Venus spins once every 243 Earth days but circles the Sun in only 225, so its day outlasts its year.",tr:"Venüs kendi ekseninde bir tur atmak için 243 Dünya günü harcarken Güneş'in etrafını sadece 225 günde döner, yani günü yılından uzundur."} },
  { id:"sci093", t:"science", d:5, k:"tf", v:false, en:{q:"Newton's second law of motion says that every action has an equal and opposite reaction."}, tr:{q:"Newton'un ikinci hareket yasası, her etkiye eşit ve zıt bir tepki olduğunu söyler."}, ex:{en:"That statement describes Newton's third law; his second law links force to mass times acceleration.",tr:"Bu ifade Newton'ın üçüncü yasasını anlatır; ikinci yasa ise kuvveti kütle ile ivmenin çarpımına bağlar."} },
  { id:"sci094", t:"science", d:5, k:"tf", v:false, en:{q:"Gregor Mendel worked out the basic laws of inheritance by breeding fruit flies."}, tr:{q:"Gregor Mendel, kalıtımın temel kurallarını meyve sinekleri yetiştirerek buldu."}, ex:{en:"Mendel worked out inheritance by breeding pea plants in his monastery garden, not fruit flies.",tr:"Mendel, kalıtım kurallarını sinekle değil, manastır bahçesinde yetiştirdiği bezelye bitkileriyle ortaya çıkardı."} },
  { id:"sci095", t:"science", d:5, k:"tf", v:true, en:{q:"Viruses can only multiply inside the cells of a living host."}, tr:{q:"Virüsler yalnızca canlı bir konağın hücreleri içinde çoğalabilir."}, ex:{en:"Viruses have no cells of their own, so they must hijack a living cell's machinery to make copies of themselves.",tr:"Virüslerin kendi hücreleri yoktur, bu yüzden kendilerini kopyalamak için canlı bir hücrenin mekanizmasını ele geçirmek zorundadırlar."} },
  { id:"sci096", t:"science", d:6, c:0, en:{q:"Who developed the general theory of relativity?",a:["Albert Einstein","Niels Bohr","Max Planck","Werner Heisenberg"]}, tr:{q:"Genel görelilik kuramını kim geliştirdi?",a:["Albert Einstein","Niels Bohr","Max Planck","Werner Heisenberg"]} },
  { id:"sci097", t:"science", d:6, c:0, en:{q:"What is the SI unit of force?",a:["Newton","Joule","Watt","Pascal"]}, tr:{q:"Kuvvetin SI birimi nedir?",a:["Newton","Joule","Watt","Pascal"]} },
  { id:"sci098", t:"science", d:6, c:0, en:{q:"Which metal is liquid at room temperature?",a:["Mercury","Lead","Sodium","Tin"]}, tr:{q:"Oda sıcaklığında sıvı hâlde bulunan metal hangisidir?",a:["Cıva","Kurşun","Sodyum","Kalay"]} },
  { id:"sci099", t:"science", d:6, c:0, en:{q:"Which organ of the human body produces insulin?",a:["The pancreas","The liver","The kidney","The thyroid"]}, tr:{q:"İnsan vücudunda insülini hangi organ üretir?",a:["Pankreas","Karaciğer","Böbrek","Tiroit"]} },
  { id:"sci100", t:"science", d:6, c:0, en:{q:"In a scientific experiment, what is the group given no treatment called?",a:["The control group","The sample group","The variable group","The test group"]}, tr:{q:"Bilimsel bir deneyde uygulama yapılmayan gruba ne ad verilir?",a:["Kontrol grubu","Örneklem grubu","Değişken grubu","Deney grubu"]} },
  { id:"sci101", t:"science", d:6, c:0, en:{q:"Which scientist is best known for developing the periodic table of elements?",a:["Dmitri Mendeleev","Antoine Lavoisier","John Dalton","Robert Boyle"]}, tr:{q:"Elementlerin periyodik tablosunu geliştirmesiyle tanınan bilim insanı kimdir?",a:["Dmitri Mendeleyev","Antoine Lavoisier","John Dalton","Robert Boyle"]} },
  { id:"sci102", t:"science", d:6, c:0, en:{q:"What are the building blocks of proteins called?",a:["Amino acids","Nucleotides","Fatty acids","Monosaccharides"]}, tr:{q:"Proteinlerin yapı taşlarına ne ad verilir?",a:["Amino asitler","Nükleotitler","Yağ asitleri","Monosakkaritler"]} },
  { id:"sci103", t:"science", d:6, c:0, en:{q:"In visible light, which colour has the longest wavelength?",a:["Red","Blue","Green","Violet"]}, tr:{q:"Görünür ışıkta en uzun dalga boyuna sahip renk hangisidir?",a:["Kırmızı","Mavi","Yeşil","Mor"]} },
  { id:"sci104", t:"science", d:6, c:0, en:{q:"Saturn's rings are made mostly of what?",a:["Water ice","Molten rock","Iron dust","Frozen methane"]}, tr:{q:"Satürn'ün halkaları büyük ölçüde neyden oluşur?",a:["Su buzu","Erimiş kaya","Demir tozu","Donmuş metan"]} },
  { id:"sci105", t:"science", d:6, c:0, en:{q:"How many bones are there in a typical adult human skeleton?",a:["206","168","254","300"]}, tr:{q:"Yetişkin bir insan iskeletinde tipik olarak kaç kemik bulunur?",a:["206","168","254","300"]} },
  { id:"sci106", t:"science", d:6, c:0, en:{q:"What does a barometer measure?",a:["Air pressure","Humidity","Wind speed","Temperature"]}, tr:{q:"Barometre neyi ölçer?",a:["Hava basıncı","Nem","Rüzgâr hızı","Sıcaklık"]} },
  { id:"sci107", t:"science", d:6, k:"tf", v:true, en:{q:"Venus spins on its axis in the opposite direction to most planets in the Solar System."}, tr:{q:"Venüs, kendi ekseni etrafında Güneş Sistemi'ndeki çoğu gezegenin tersi yönde döner."} },
  { id:"sci108", t:"science", d:6, k:"tf", v:false, en:{q:"The left ventricle of the human heart pumps blood to the lungs."}, tr:{q:"İnsan kalbinde sol karıncık, kanı akciğerlere pompalar."} },
  { id:"sci109", t:"science", d:6, k:"tf", v:true, en:{q:"In DNA, the base adenine always pairs with thymine."}, tr:{q:"DNA'da adenin bazı her zaman timin ile eşleşir."} },
  { id:"sci110", t:"science", d:6, k:"tf", v:false, en:{q:"An ozone molecule is made up of two oxygen atoms."}, tr:{q:"Bir ozon molekülü iki oksijen atomundan oluşur."} },
  { id:"sci111", t:"science", d:6, k:"tf", v:true, en:{q:"In a vacuum, a hammer and a feather dropped from the same height land at the same time."}, tr:{q:"Vakumda aynı yükseklikten bırakılan bir çekiç ile bir tüy yere aynı anda düşer."} },
  { id:"sci112", t:"science", d:6, k:"tf", v:false, en:{q:"Thomas Edison championed alternating current, while Nikola Tesla backed direct current."}, tr:{q:"Thomas Edison alternatif akımı, Nikola Tesla ise doğru akımı savundu."} },
  { id:"sci113", t:"science", d:7, c:0, en:{q:"What is the freezing point of water on the Kelvin scale?",a:["273.15 K","0 K","100 K","373.15 K"]}, tr:{q:"Suyun donma noktası Kelvin ölçeğinde kaçtır?",a:["273,15 K","0 K","100 K","373,15 K"]} },
  { id:"sci114", t:"science", d:7, c:0, en:{q:"Which subatomic particle carries no electric charge?",a:["Neutron","Proton","Electron","Positron"]}, tr:{q:"Hangi atom altı parçacık elektrik yükü taşımaz?",a:["Nötron","Proton","Elektron","Pozitron"]} },
  { id:"sci115", t:"science", d:7, c:0, en:{q:"Which lander made the first soft landing on a comet, in 2014?",a:["Philae","Huygens","Beagle 2","Viking 1"]}, tr:{q:"2014'te bir kuyruklu yıldıza ilk yumuşak inişi hangi araç gerçekleştirdi?",a:["Philae","Huygens","Beagle 2","Viking 1"]} },
  { id:"sci116", t:"science", d:7, c:0, en:{q:"Which noble gas was the first to be shown to form a chemical compound, in 1962?",a:["Xenon","Helium","Neon","Argon"]}, tr:{q:"1962'de kimyasal bileşik oluşturduğu ilk kez gösterilen soy gaz hangisidir?",a:["Ksenon","Helyum","Neon","Argon"]} },
  { id:"sci117", t:"science", d:7, c:0, en:{q:"Which naturalist arrived at the idea of natural selection independently of Darwin?",a:["Alfred Russel Wallace","Thomas Huxley","Charles Lyell","Gregor Mendel"]}, tr:{q:"Doğal seçilim fikrine Darwin'den bağımsız olarak hangi doğa bilimci ulaştı?",a:["Alfred Russel Wallace","Thomas Huxley","Charles Lyell","Gregor Mendel"]} },
  { id:"sci118", t:"science", d:7, c:0, en:{q:"Which philosopher made falsifiability the key test of a scientific theory?",a:["Karl Popper","Thomas Kuhn","Francis Bacon","Auguste Comte"]}, tr:{q:"Yanlışlanabilirliği bilimsel kuramın temel ölçütü sayan filozof kimdir?",a:["Karl Popper","Thomas Kuhn","Francis Bacon","Auguste Comte"]} },
  { id:"sci119", t:"science", d:7, c:0, en:{q:"One parsec is equal to roughly how many light years?",a:["About 3.26","About 1.6","About 9.5","About 26"]}, tr:{q:"Bir parsek kabaca kaç ışık yılına eşittir?",a:["Yaklaşık 3,26","Yaklaşık 1,6","Yaklaşık 9,5","Yaklaşık 26"]} },
  { id:"sci120", t:"science", d:7, c:0, en:{q:"Which metal acts as the catalyst in the Haber process for making ammonia?",a:["Iron","Platinum","Nickel","Copper"]}, tr:{q:"Amonyak üreten Haber prosesinde katalizör olarak hangi metal kullanılır?",a:["Demir","Platin","Nikel","Bakır"]} },
  { id:"sci121", t:"science", d:7, c:0, en:{q:"The Mohorovicic discontinuity separates Earth's crust from which layer?",a:["The mantle","The outer core","The inner core","The hydrosphere"]}, tr:{q:"Mohorovičić süreksizliği, Dünya'nın kabuğunu hangi katmandan ayırır?",a:["Manto","Dış çekirdek","İç çekirdek","Hidrosfer"]} },
  { id:"sci122", t:"science", d:7, k:"tf", v:false, en:{q:"Aqua regia, the acid mixture that can dissolve gold, is nitric acid mixed with sulfuric acid."}, tr:{q:"Altını çözebilen asit karışımı olan kral suyu, nitrik asit ile sülfürik asidin karışımıdır."} },
  { id:"sci123", t:"science", d:7, k:"tf", v:false, en:{q:"The human appendix is a small pouch attached to the small intestine."}, tr:{q:"İnsanda apandis, ince bağırsağa bağlı küçük bir kesedir."} },
  { id:"sci124", t:"science", d:7, k:"tf", v:true, en:{q:"Isaac Newton spent his later years in charge of England's Royal Mint."}, tr:{q:"Isaac Newton, ileri yaşlarında İngiltere Kraliyet Darphanesi'nin başında görev yaptı."} },
  { id:"sci125", t:"science", d:7, k:"tf", v:false, en:{q:"Mitochondria carry their own DNA, which a child inherits from its father."}, tr:{q:"Mitokondrilerin kendine ait DNA'sı vardır ve çocuk bu DNA'yı babasından alır."} },
  { id:"sci126", t:"science", d:8, c:0, en:{q:"Which enzyme unwinds the DNA double helix during replication?",a:["Helicase","Ligase","Polymerase","Primase"]}, tr:{q:"DNA çift sarmalını eşlenme sırasında hangi enzim açar?",a:["Helikaz","Ligaz","Polimeraz","Primaz"]} },
  { id:"sci127", t:"science", d:8, c:0, en:{q:"Heisenberg's uncertainty principle limits simultaneous knowledge of which pair?",a:["Position and momentum","Mass and charge","Energy and charge","Spin and mass"]}, tr:{q:"Heisenberg belirsizlik ilkesi hangi ikilinin aynı anda bilinmesini sınırlar?",a:["Konum ve momentum","Kütle ve yük","Enerji ve yük","Spin ve kütle"]} },
  { id:"sci128", t:"science", d:8, c:0, en:{q:"The Chandrasekhar limit caps a white dwarf's mass at roughly what value?",a:["1.4 solar masses","0.5 solar masses","3.2 solar masses","8 solar masses"]}, tr:{q:"Chandrasekhar sınırı bir beyaz cücenin kütlesini yaklaşık kaçla sınırlar?",a:["1,4 Güneş kütlesi","0,5 Güneş kütlesi","3,2 Güneş kütlesi","8 Güneş kütlesi"]} },
  { id:"sci129", t:"science", d:8, c:0, en:{q:"According to Noether's theorem, every conservation law arises from what?",a:["A continuous symmetry","A quantised energy level","A conserved wavefunction","A relativistic reference frame"]}, tr:{q:"Noether teoremine göre her korunum yasası neyden kaynaklanır?",a:["Sürekli bir simetriden","Kuantumlu bir enerji düzeyinden","Korunan bir dalga fonksiyonundan","Göreli bir referans çerçevesinden"]} },
  { id:"sci130", t:"science", d:8, c:0, en:{q:"Which quantum number determines the shape of an atomic orbital?",a:["Azimuthal (l)","Principal (n)","Magnetic (mₗ)","Spin (mₛ)"]}, tr:{q:"Bir atom orbitalinin şeklini hangi kuantum sayısı belirler?",a:["Açısal momentum (l)","Baş kuantum sayısı (n)","Manyetik (mₗ)","Spin (mₛ)"]} },
  { id:"sci131", t:"science", d:8, c:0, en:{q:"The vagus nerve is which numbered cranial nerve?",a:["Tenth","Fifth","Seventh","Twelfth"]}, tr:{q:"Vagus siniri kaçıncı kraniyal sinirdir?",a:["Onuncu","Beşinci","Yedinci","On ikinci"]} },
  { id:"sci132", t:"science", d:8, c:0, en:{q:"Which cells of the pancreatic islets secrete glucagon?",a:["Alpha cells","Beta cells","Delta cells","Acinar cells"]}, tr:{q:"Pankreas adacıklarında glukagonu hangi hücreler salgılar?",a:["Alfa hücreleri","Beta hücreleri","Delta hücreleri","Asiner hücreler"]} },
  { id:"sci133", t:"science", d:8, c:0, en:{q:"Who first showed light travels at a finite speed, using Jupiter's moon Io?",a:["Ole Rømer","Galileo Galilei","Christiaan Huygens","Isaac Newton"]}, tr:{q:"Jüpiter'in uydusu Io'yu kullanarak ışık hızının sonlu olduğunu ilk kim gösterdi?",a:["Ole Rømer","Galileo Galilei","Christiaan Huygens","Isaac Newton"]} },
  { id:"sci134", t:"science", d:8, c:0, en:{q:"What is it called when a superconductor expels magnetic fields from its interior?",a:["The Meissner effect","The Hall effect","The Zeeman effect","The Faraday effect"]}, tr:{q:"Bir süperiletkenin manyetik alanı içinden dışarı atmasına ne ad verilir?",a:["Meissner etkisi","Hall etkisi","Zeeman etkisi","Faraday etkisi"]} },
  { id:"sci135", t:"science", d:8, k:"tf", v:true, en:{q:"Ganymede is the only moon in the Solar System known to generate its own magnetic field."}, tr:{q:"Güneş Sistemi'nde kendi manyetik alanını üreten bilinen tek uydu Ganymede'dir."} },
  { id:"sci136", t:"science", d:8, k:"tf", v:false, en:{q:"The oxygen plants release during photosynthesis comes from the carbon dioxide they take in."}, tr:{q:"Bitkilerin fotosentezde saldığı oksijen, havadan aldıkları karbondioksitten gelir."} },
  { id:"sci137", t:"science", d:8, k:"tf", v:true, en:{q:"Hydrofluoric acid is a weak acid in water, while hydrochloric and hydroiodic acid are strong."}, tr:{q:"Hidroflorik asit suda zayıf bir asittir; hidroklorik ve hidroiyodik asit ise kuvvetlidir."} },
  { id:"sci138", t:"science", d:8, k:"tf", v:false, en:{q:"Since 2019 the kilogram has been defined by fixing an exact value for the Avogadro constant."}, tr:{q:"2019'dan beri kilogram, Avogadro sabitine kesin bir değer atanarak tanımlanmaktadır."} },
  { id:"sci139", t:"science", d:8, k:"tf", v:true, en:{q:"The hyoid bone in the neck is the only human bone that forms no joint with another bone."}, tr:{q:"Boyundaki hyoid kemiği, başka hiçbir kemikle eklem oluşturmayan tek insan kemiğidir."} },
  { id:"sci140", t:"science", d:8, k:"tf", v:false, en:{q:"Enrico Fermi's team achieved the first controlled nuclear chain reaction at Los Alamos in 1942."}, tr:{q:"Enrico Fermi'nin ekibi ilk kontrollü nükleer zincirleme tepkimeyi 1942'de Los Alamos'ta gerçekleştirdi."} }
);
